export function mount(root,{api},kind){
 const asg=kind==='asg';
 root.innerHTML=`<h2>${asg?'信号发生器':'PID'}</h2><p class="muted">${asg?'配置 ASG0 的波形与实际输出。':'配置 PID0；切换到其他页面时，反馈继续保持。'}</p><div class="card"><div class="fields">${asg?'<label>波形<select id="waveform"><option value="ramp">三角扫描 / ramp</option><option value="sin">正弦 / sin</option><option value="square">方波 / square</option><option value="dc">直流 / dc</option></select></label><label>频率 / Hz<input id="frequency" type="number" min="0" step="any" placeholder="填写频率" required></label><label>幅值 / V<input id="amplitude" type="number" min="0" step="any" placeholder="填写幅值" required></label><label>偏置 / V<input id="offset" type="number" step="any" value="0" required></label>':'<label>输入<input id="input" value="in1"></label><label>目标值 / V<input id="setpoint" type="number" step="any" placeholder="填写目标" required></label><label>P<input id="p" type="number" step="any" placeholder="填写 P" required></label><label>I / Hz<input id="i" type="number" step="any" placeholder="填写 I" required></label>'}<label>输出<select id="output_direct"><option value="off">关闭</option><option value="out1">OUT1</option><option value="out2">OUT2</option></select></label></div><p><button id="apply" class="primary">应用设置</button> <button id="off" class="danger">关闭${asg?'信号':'反馈'}输出</button></p><p class="muted">应用设置会改变仪器状态；各参数依次写入，失败时需检查已生效的设置。</p><pre id="result">尚未操作</pre></div>`;
 async function run(settings){try{const r=await api(kind+'/configure',{settings});root.querySelector('#result').textContent=JSON.stringify(r.applied,null,2);}catch{}}
 root.querySelector('#apply').onclick=()=>{const settings={};for(const el of root.querySelectorAll('input,select')){if(!el.reportValidity()||el.value==='')return;settings[el.id]=el.type==='number'?Number(el.value):el.value;}run(settings);};
 root.querySelector('#off').onclick=()=>run(asg?{output_direct:'off'}:{p:0,i:0,output_direct:'off'});
}
